#!/bin/bash
set -eu
export PYTHONDONTWRITEBYTECODE=1
exec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PY'
import base64,hashlib,json,os
from pathlib import Path
phase=Path('/home/loosqk/robot-checks/position-return-20261010-r1/head1-p32-reverse-r16')
assert phase.is_dir() and not phase.is_symlink()
raw=base64.b64decode('',validate=True)
path=phase/'field_confirmation_r16.json'
with path.open("xb") as f:f.write(raw);f.flush();os.fsync(f.fileno())
assert path.read_bytes()==raw
print(json.dumps({"uploaded":str(path),"sha256":hashlib.sha256(raw).hexdigest(),"bytes":len(raw)}),flush=True)
